    wire dat_ava;
    wire crc_valid;
    wire command_index_mismatch;
    wire timeout_expired;
    wire response_present;

    assign CMDI        = CMD_SET_REG[13:8];
    assign WORD_SELECT = CMD_SET_REG[7:6];
    assign CICE        = CMD_SET_REG[4];
    assign CRCE        = CMD_SET_REG[3];
    assign RTS         = CMD_SET_REG[1:0];

    assign dat_ava                = status[DAT_AVA_BIT];
    assign crc_valid              = status[CRC_VALID_BIT];
    assign command_index_mismatch = (cmd_out[37:32] != cmd_in[37:32]);
    assign timeout_expired        = (Watchdog_Cnt >= TIMEOUT_REG);
    assign response_present       = (response_size != 7'b0000000);


    // ========================================================================
    // B2 – Combinational next-state logic
    // ========================================================================
    always @(state or New_CMD or ack_in_int or complete) begin
        next_state = IDLE;
        case (state)
            IDLE: begin
                if (New_CMD) begin
                    next_state = SETUP;
                end else begin
                    next_state = IDLE;
                end
            end

            SETUP: begin
                if (ack_in_int) begin
                    next_state = EXECUTE;
                end else begin
                    next_state = SETUP;
                end
            end

            EXECUTE: begin
                if (complete) begin
                    next_state = IDLE;
                end else begin
                    next_state = EXECUTE;
                end
            end

            default: begin
                next_state = IDLE;
            end
        endcase
    end


    // ========================================================================
    // B3 – Sequential FSM state register (async reset)
    // ========================================================================
    always @(posedge CLK_PAD_IO or posedge RST_PAD_I) begin
        if (RST_PAD_I) begin
            state <= #1 IDLE;
        end else begin
            state <= #1 next_state;
        end
    end


    // ========================================================================
    // B4 – Combinational command/settings assembly
    // ========================================================================
    always @(CMD_SET_REG or ARG_REG or data_read or data_write) begin
        case (CMD_SET_REG[1:0])
            2'b10: begin
                response_size_comb = small_rsp;
            end
            2'b11: begin
                response_size_comb = small_rsp;
            end
            2'b01: begin
                response_size_comb = big_rsp;
            end
            default: begin
                response_size_comb = 7'b0000000;
            end
        endcase

        next_cmd_out = {2'b01, CMD_SET_REG[13:8], ARG_REG};
        next_settings = {1'b0, CMD_SET_REG[7:6], data_read, data_write, 3'b111, CMD_SET_REG[3], response_size_comb};
    end


    // ========================================================================
    // B5 – Sequential debounce logic (async reset)
    // ========================================================================
    always @(posedge CLK_PAD_IO or posedge RST_PAD_I) begin
        if (RST_PAD_I) begin
            debounce     <= 4'b0000;
            card_present <= 1'b0;
        end else begin
            if (!card_detect) begin
                if (debounce != 4'b1111) begin
                    debounce <= debounce + 4'b0001;
                end
            end else begin
                debounce <= 4'b0000;
            end

            if (debounce == 4'b1111) begin
                card_present <= 1'b1;
            end else begin
                card_present <= 1'b0;
            end
        end
    end


    // ========================================================================
    // B6 – Sequential synchronisers for req_in / ack_in (async reset)
    // ========================================================================
    always @(posedge CLK_PAD_IO or posedge RST_PAD_I) begin
        if (RST_PAD_I) begin
            req_q      <= 1'b0;
            req_in_int <= 1'b0;
            ack_q      <= 1'b0;
            ack_in_int <= 1'b0;
        end else begin
            req_q      <= req_in;
            req_in_int <= req_q;
            ack_q      <= ack_in;
            ack_in_int <= ack_q;
        end
    end


    // ========================================================================
    // B7 – Sequential per-state operations (output updates, watchdog,
    //      handshake, interrupts, response capture)
    // ========================================================================
    always @(posedge CLK_PAD_IO or posedge RST_PAD_I) begin
        if (RST_PAD_I) begin
            CRC_check_enable   <= 1'b0;
            complete           <= 1'b0;
            RESP_1_REG         <= 32'b00000000000000000000000000000000;
            ERR_INT_REG        <= 5'b00000;
            NORMAL_INT_REG     <= 16'b0000000000000000;
            STATUS_REG         <= 16'b0000000000000000;
            status             <= 8'b00000000;
            cmd_out            <= 40'b0000000000000000000000000000000000000000;
            settings           <= 16'b0000000000000000;
            response_size      <= 7'b0000000;
            req_out            <= 1'b0;
            index_check_enable <= 1'b0;
            ack_out            <= 1'b0;
            Watchdog_Cnt       <= 16'b0000000000000000;
            go_idle_o          <= 1'b0;
        end else begin
            NORMAL_INT_REG[CARD_INSERT_INT] <= card_present;
            NORMAL_INT_REG[CARD_REMOVE_INT] <= ~card_present;
            complete <= 1'b0;

            case (state)
                IDLE: begin
                    go_idle_o            <= 1'b0;
                    req_out              <= 1'b0;
                    ack_out              <= 1'b0;
                    STATUS_REG[CICMD]    <= 1'b0;

                    if (req_in_int) begin
                        status  <= serial_status;
                        ack_out <= 1'b1;
                    end
                end

                SETUP: begin
                    NORMAL_INT_REG <= 16'b0000000000000000;
                    ERR_INT_REG    <= 5'b00000;
                    STATUS_REG     <= 16'b0000000000000000;
                    STATUS_REG[CICMD] <= 1'b1;

                    index_check_enable <= CICE;
                    CRC_check_enable   <= CRCE;
                    response_size      <= response_size_comb;
                    cmd_out            <= next_cmd_out;
                    settings           <= next_settings;
                    Watchdog_Cnt       <= 16'b0000000000000000;
                end

                EXECUTE: begin
                    Watchdog_Cnt <= Watchdog_Cnt + 16'b0000000000000001;

                    if (timeout_expired) begin
                        ERR_INT_REG[CTE] = 1'b1;
                        NORMAL_INT_REG[EI] = 1'b1;
                        go_idle_o = 1'b1;
                        if (ack_in) begin
                            complete <= 1'b1;
                        end
                    end

                    req_out <= 1'b0;
                    ack_out <= 1'b0;

                    if (ack_in_int) begin
                        req_out <= 1'b1;
                    end else if (req_in_int) begin
                        status  <= serial_status;
                        ack_out <= 1'b1;

                        if (serial_status[DAT_AVA_BIT]) begin
                            complete <= 1'b1;
                            NORMAL_INT_REG[EI] <= 1'b0;

                            if (CRC_check_enable && !serial_status[CRC_VALID_BIT]) begin
                                ERR_INT_REG[CCRCE] <= 1'b1;
                                NORMAL_INT_REG[EI] <= 1'b1;
                            end

                            if (index_check_enable && command_index_mismatch) begin
                                ERR_INT_REG[CIE] <= 1'b1;
                                NORMAL_INT_REG[EI] <= 1'b1;
                            end

                            NORMAL_INT_REG[CC] <= 1'b1;

                            if (response_present) begin
                                RESP_1_REG <= cmd_in[31:0];
                            end
                        end
                    end
                end

                default: begin
                    go_idle_o <= 1'b0;
                    req_out   <= 1'b0;
                    ack_out   <= 1'b0;
                end
            endcase

            if (ERR_INT_RST) begin
                ERR_INT_REG <= 5'b00000;
            end
            if (NORMAL_INT_RST) begin
                NORMAL_INT_REG <= 16'b0000000000000000;
            end
        end
    end

endmodule

// support source: sd_cmd_master_ref.sv
`include "sd_defines.v"
module ref_sd_cmd_master(
input CLK_PAD_IO,

input RST_PAD_I,
input New_CMD,
input data_write,
input data_read,



input [31:0] ARG_REG,
input [13:0] CMD_SET_REG,
input [15:0] TIMEOUT_REG,
output reg [15:0] STATUS_REG,
output reg [31:0] RESP_1_REG,

output reg [4:0] ERR_INT_REG, 
output reg [15:0] NORMAL_INT_REG, 
input ERR_INT_RST,
input NORMAL_INT_RST,

output reg [15:0] settings,
output reg go_idle_o,
output reg  [39:0] cmd_out,
output reg req_out,
output reg ack_out,
input req_in,
input ack_in,
input [39:0] cmd_in,
input [7:0] serial_status,
input card_detect
);



`define dat_ava status[6]
`define crc_valid status[5] 
`define small_rsp 7'b0101000
`define big_rsp 7'b1111111

`define CMDI CMD_SET_REG[13:8]
`define WORD_SELECT CMD_SET_REG[7:6]
`define CICE CMD_SET_REG[4]
`define CRCE CMD_SET_REG[3]
`define RTS CMD_SET_REG[1:0]
`define CTE ERR_INT_REG[0]
`define CCRCE ERR_INT_REG[1]
`define CIE  ERR_INT_REG[3]
`define EI NORMAL_INT_REG[15]
`define CC  NORMAL_INT_REG[0]
`define CICMD STATUS_REG[0]


//-----------Types--------------------------------------------------------

reg CRC_check_enable;
reg index_check_enable;
reg [6:0]response_size;


reg card_present;


reg [3:0]debounce;

reg [15:0]status;
reg [15:0]  Watchdog_Cnt;
reg complete;



parameter SIZE = 3;
reg [SIZE-1:0] state;
reg [SIZE-1:0] next_state;

parameter IDLE   =  3'b001;
parameter SETUP   =  3'b010;
parameter EXECUTE  =  3'b100;
reg ack_in_int;
reg ack_q;
reg req_q;
reg req_in_int;

always @ (posedge CLK_PAD_IO or posedge RST_PAD_I   )
begin
  if (RST_PAD_I) begin
    req_q<=0;
    req_in_int<=0;
 end 
else begin
  req_q<=req_in;  
  req_in_int<=req_q;
end
end  

//---------------Input ports---------------


always @ (posedge CLK_PAD_IO or posedge RST_PAD_I   )
begin
  if (RST_PAD_I) begin
    debounce<=0;
    card_present<=0;
 end 
else begin
	if (!card_detect) begin//Card present
		if (debounce!=4'b1111)
			debounce<=debounce+1'b1;
	end
	else	
		 debounce<=0;

	if (debounce==4'b1111)
       card_present<=1'b1;
	else 
	   card_present<=1'b0;
end
end  



always @ (posedge CLK_PAD_IO or posedge RST_PAD_I   )
begin
  if (RST_PAD_I) begin
    ack_q<=0;
    ack_in_int<=0;
 end 
else begin
  ack_q<=ack_in;
  ack_in_int<=ack_q;
end


end



always @ ( state or New_CMD or complete or ack_in_int )
begin : FSM_COMBO
    next_state = 0;

 case(state)
 IDLE:   begin
      if (New_CMD) begin
          next_state = SETUP;
      end     
      else begin
         next_state = IDLE;
      end   
 end       
 SETUP:begin
    if (ack_in_int)             
       next_state = EXECUTE;  
     else   
       next_state = SETUP;
   end  
 EXECUTE:    begin
       if (complete) begin
          next_state = IDLE;
      end     
      else begin
         next_state = EXECUTE;
      end
 end       


 default : next_state  = IDLE;

 endcase 

end




always @ (posedge CLK_PAD_IO or posedge RST_PAD_I   )
begin : FSM_SEQ
  if (RST_PAD_I ) begin
    state <= #1 IDLE;
 end 
 else begin
    state <= #1 next_state;
 end
end



always @ (posedge CLK_PAD_IO or posedge RST_PAD_I   )
begin  
 if (RST_PAD_I ) begin 
    CRC_check_enable=0;
    complete =0;
    RESP_1_REG = 0;

    ERR_INT_REG =0;
    NORMAL_INT_REG=0;
    STATUS_REG=0;
    status=0; 
    cmd_out =0 ;
    settings=0;
    response_size=0;
    req_out=0;
    index_check_enable=0; 
    ack_out=0; 
    Watchdog_Cnt=0;

    `CCRCE=0;
    `EI = 0;
    `CC = 0; 
     go_idle_o=0;  
 end 
 else begin
 NORMAL_INT_REG[1] = card_present;
 NORMAL_INT_REG[2] = ~card_present;
 complete=0;
 case(state)
 IDLE: begin
    go_idle_o=0;  
    req_out=0;
		ack_out =0;
		`CICMD =0; 
    if ( req_in_int == 1) begin     //Status change
        status=serial_status;
        ack_out = 1;


    end
 end
 SETUP:  begin

     NORMAL_INT_REG=0; 
     ERR_INT_REG =0;

     index_check_enable = `CICE; 
     CRC_check_enable = `CRCE;

    if ( (`RTS  == 2'b10 ) || ( `RTS == 2'b11)) begin
      response_size =  7'b0101000; 
    end
    else if (`RTS == 2'b01) begin
      response_size = 7'b1111111; 
    end    
    else begin
       response_size=0;
    end    

    cmd_out[39:38]=2'b01;         
    cmd_out[37:32]=`CMDI;  //CMD_INDEX
    cmd_out[31:0]= ARG_REG;           //CMD_Argument      
    settings[14:13]=`WORD_SELECT;             //Reserved
    settings[12] = data_read; //Type of command
    settings[11] = data_write;
    settings[10:8]=3'b111;            //Delay
    settings[7]=`CRCE;         //CRC-check
    settings[6:0]=response_size;   //response size    
    Watchdog_Cnt = 0;

    `CICMD =1;    
 end   

 EXECUTE: begin   
    Watchdog_Cnt = Watchdog_Cnt +1;
    if (Watchdog_Cnt>TIMEOUT_REG) begin
      `CTE=1;
      `EI = 1;
      if (ack_in == 1) begin
         complete=1;
      end   
      go_idle_o=1; 
    end

    //Default
    req_out=0;
		ack_out =0;

    //Start sending when serial module is ready
   	if (ack_in_int == 1) begin	    	     
	    		req_out =1;	   			   		
	  end	
	   //Incoming New Status 
	  else if ( req_in_int == 1) begin   
        status=serial_status;

        ack_out = 1; 
        if ( `dat_ava ) begin //Data avaible
           complete=1;
            `EI = 0;

           if (CRC_check_enable & ~`crc_valid) begin 
            `CCRCE=1;
            `EI = 1;

           end 
           if (index_check_enable &  (cmd_out[37:32] != cmd_in [37:32]) ) begin
            `CIE=1;
            `EI = 1;

           end


             `CC = 1;  

             if (response_size !=0)
              RESP_1_REG=cmd_in[31:0];

          // end 
         end ////Data avaible
       end //Status change
     end //EXECUTE state
   endcase
   if (ERR_INT_RST)
     ERR_INT_REG=0;
   if (NORMAL_INT_RST)
     NORMAL_INT_REG=0;
  end
end

endmodule


// support source: sd_cmd_master_stimulus_gen.sv
module stimulus_gen (
	input CLK_PAD_IO,

	output logic RST_PAD_I, New_CMD, 
    output logic data_write, data_read, 
    output logic ERR_INT_RST, NORMAL_INT_RST, 
    output logic req_in, ack_in, card_detect,

    output [31:0] ARG_REG,
    output [13:0] CMD_SET_REG,
    output [15:0] TIMEOUT_REG,
    output [39:0] cmd_in,
    output [7:0] serial_status,

	output reg[511:0] wavedrom_title,
	output reg wavedrom_enable,
	tb_match
);
	reg reset;
	assign RST_PAD_I = reset;


	task reset_test(async=0);
		bit arfail, srfail, datafail;

		@(posedge CLK_PAD_IO);
		@(posedge CLK_PAD_IO) reset = 0;
		repeat(3) @(posedge CLK_PAD_IO);

		@(negedge CLK_PAD_IO) begin datafail = !tb_match ; reset = 1; end
		@(posedge CLK_PAD_IO) arfail = !tb_match;
		@(posedge CLK_PAD_IO) begin
			srfail = !tb_match;
			reset = 0;
		end
		if (srfail)
			$display("Hint: Your reset doesn't seem to be working.");
		else if (arfail && (async || !datafail))
			$display("Hint: Your reset should be %0s, but doesn't appear to be.", async ? "asynchronous" : "synchronous");
		// Don't warn about synchronous reset if the half-cycle before is already wrong. It's more likely
		// a functionality error than the reset being implemented asynchronously.

	endtask

// Add two ports to module stimulus_gen:
//    output [511:0] wavedrom_title
//    output reg wavedrom_enable

	task wavedrom_start(input[511:0] title = "");
	endtask

	task wavedrom_stop;
		#1;
	endtask	



	initial begin
		repeat(3)@(posedge CLK_PAD_IO) reset = 0;
		repeat(3)@(posedge CLK_PAD_IO) reset = 1;
		New_CMD = 0;
		data_write = 0;
		data_read = 0;
		ERR_INT_RST = 0;
		NORMAL_INT_RST = 0;
		req_in = 0;
		ack_in = 0;
		card_detect = 0;
		cmd_in = 0;
		serial_status = 0;
		ARG_REG = 0;
		CMD_SET_REG = 0;
		TIMEOUT_REG = 0;

		repeat(3)@(posedge CLK_PAD_IO) reset = 0;

		wavedrom_start("Asynchronous reset");
		reset_test(1);
		wavedrom_stop();


		repeat(10)@(posedge CLK_PAD_IO) reset = 1;
		repeat(10)@(posedge CLK_PAD_IO) reset = 0;
		repeat(10)@(posedge CLK_PAD_IO) TIMEOUT_REG = 15'h10;
		repeat(10)@(posedge CLK_PAD_IO) New_CMD = 1;
		repeat(10)@(posedge CLK_PAD_IO) ack_in = 1;
		repeat(10)@(posedge CLK_PAD_IO) ack_in = 0;
		repeat(10)@(posedge CLK_PAD_IO) ack_in = 1;
		repeat(10)@(posedge CLK_PAD_IO) ERR_INT_RST= 1;
		repeat(10)@(posedge CLK_PAD_IO) NORMAL_INT_RST=1;


        @(posedge CLK_PAD_IO);
		repeat(5000) @(posedge CLK_PAD_IO, negedge CLK_PAD_IO) begin
			New_CMD = ($random%2);
            data_write = ($random%2);
            data_read = ($random%2);
            ERR_INT_RST = ($random%2);
            NORMAL_INT_RST = ($random%2);
            req_in = ($random%2);
            ack_in = ($random%2);
            card_detect = ($random%2);

            ARG_REG = $random;
            CMD_SET_REG = $random;
            TIMEOUT_REG = $random;
            cmd_in = {$random, $random[7:0]};
            serial_status = $random;
			reset = !($random & 31);
		end

		#1 $finish;
	end

endmodule

